$Text=$Text.Replace('UI();LoadToken();','UI();Premium();LoadToken();')
$marker=' protected override void OnFormClosed(FormClosedEventArgs e)'
$premium=@'
 Control FindText(Control root,string text){foreach(Control c in root.Controls){if(c.Text==text)return c;Control z=FindText(c,text);if(z!=null)return z;}return null;}
 Label AddLabel(Control parent,string text,int x,int y,int w,int h,float size,bool bold,Color color){Label l=new Label();l.Text=text;l.SetBounds(x,y,w,h);l.Font=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular);l.ForeColor=color;l.BackColor=Color.Transparent;parent.Controls.Add(l);return l;}
 void Premium(){
